#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "clip_hierarchy.h"
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("usage: inspect_channel_bindings session.dmx");auto g=loadGraph(argv[1]);auto roots=hierarchyRefs(g,g.elements.at(0),"activeClip",1);ClipHierarchy h(g,roots.at(0));std::map<std::string,uint64_t> counts;std::set<std::string> shownLogs;
 for(auto i:h.channels){auto&e=g.elements[i];for(auto side:{"from","to"}){auto refs=hierarchyRefs(g,e,(std::string(side)+"Element").c_str(),1);auto*a=namedAttribute(g,e,(std::string(side)+"Attribute").c_str());auto*idx=namedAttribute(g,e,(std::string(side)+"Index").c_str());if(refs.empty()){++counts[std::string(side)+":null"];continue;}if(!a||a->type!=5||a->values.size()!=1||!idx||idx->type!=2||idx->values.size()!=1)throw std::runtime_error("invalid channel binding");auto&target=g.elements[refs[0]];auto*dest=namedAttribute(g,target,a->values[0].text.c_str());++counts[std::string(side)+":"+g.strings[target.type]+":"+(dest?"existing":"missing")];if(dest)++counts[std::string(side)+":index="+std::to_string(wireInt(idx->values[0]))+":type="+std::to_string(dest->type)];}
 auto logs=hierarchyRefs(g,e,"log",1);for(auto log:logs){auto&le=g.elements[log];auto&t=g.strings[le.type];++counts["log:"+t];if(shownLogs.insert(t).second){std::cout<<"schema "<<t<<'\n';for(auto&a:le.attributes){std::cout<<g.strings[a.name]<<" type="<<unsigned(a.type)<<" count="<<a.values.size();if(a.type==1||a.type==15)for(auto&v:a.values)if(v.reference<g.elements.size())std::cout<<" ->"<<g.strings[g.elements[v.reference].type];std::cout<<'\n';}}}
 }for(auto&c:counts)std::cout<<c.first<<'='<<c.second<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
